scripts.preversion:
node -e "
const fs=require('fs');
const pkg=JSON.parse(fs.readFileSync('package.json'));
const cfgPath='config.json';
let cfg={};
if(fs.existsSync(cfgPath)) cfg=JSON.parse(fs.readFileSync(cfgPath));
cfg.version=pkg.version;
fs.writeFileSync(cfgPath, JSON.stringify(cfg,null,2)+'\n');
console.log('  → 同步 config.json version:', pkg.version);
"

scripts.version:
node -e "
const {execSync}=require('child_process');
const fs=require('fs');
const pkg=JSON.parse(fs.readFileSync('package.json'));
const zipFile='../server/src/main/resources/crm_agent-v'+pkg.version+'.zip';
try { execSync('rm -f '+zipFile, {stdio:'pipe'}); } catch {}
try { execSync('cd .. && zip -r '+zipFile+' crm_agent -x "*/node_modules/*" "*/data/*" "*/.git/*" "*.bak" "release/*" "../release/*"', {stdio:'pipe'}); console.log('  → 打包 '+zipFile); } catch(e) { console.log('  → zip 跳过:', zipFile); }
"
